INSERT INTO premium_prompts (prompt_id, prompt_text, take_prompts)
VALUES
  ('CTA-01', 'The character maintains the exact identity, face, hairstyle, clothing and environment from the reference image.

Keep the smartphone hand stable.

Using only the free hand, naturally raise the index finger and point toward the lower area of the frame.

Perform two clear downward pointing gestures.

The hand must remain around waist-to-chest distance from the body and must NOT move close to the camera lens.

Movement is smooth, controlled and natural.

Maintain relaxed posture and a subtle confident expression.

Static mirror-selfie framing.

No camera zoom.
No camera shake.
No hand covering the lens.
No waving.
No clothing changes.
No facial identity changes.
No extra fingers.
No distorted hands.
No speech.
No lip sync.', NULL),
  ('TRANSICAO-01', 'Preserve the exact character, face, outfit, smartphone and environment from the reference image.

The hand holding the smartphone remains stable.

The free hand opens naturally with the palm facing the camera.

Move the open palm smoothly toward the lens in one continuous controlled movement.

The palm progressively fills the frame until it completely covers the camera.

End with the entire frame naturally obscured by the palm.

Do not wave.
Do not point.
Do not create a peace sign.
Do not change the outfit.
Do not change facial identity.
No camera zoom.
No sudden acceleration.
No extra fingers.
No distorted hand anatomy.
No speech.
No lip sync.', NULL),
  ('CORPO-01', 'Preserve the character and environment from the reference image.

The subject takes one small natural step toward the camera while maintaining relaxed posture.

After the step, subtly shift body weight to one side and settle into a confident natural pose.

Keep shoulders relaxed and body movement fluid.

Maintain exact facial identity, clothing and proportions.

No running.
No lunging.
No exaggerated hip movement.
No camera zoom.
No body deformation.
No clothing transformation.
No speech.
No lip sync.', NULL),
  ('CAMERA-01', 'Preserve the subject, product and environment exactly as shown in the reference.

Create a slow physical camera push-in toward the main subject.

The camera moves smoothly forward through space while maintaining the same focal perspective.

The subject remains mostly still.

Maintain realistic parallax between foreground and background.

No digital zoom.
No sudden acceleration.
No camera shake.
No subject deformation.
No environment transformation.
No added objects.', NULL),
  ('UGC-MODA-001', 'Create an ultra-realistic vertical 9:16 UGC mirror-selfie product video. The model wears a blazer in front of a minimal bedroom mirror while the smartphone completely covers the face during the entire video. Preserve the person, body proportions, outfit, blazer design and environment from the reference. Start in a relaxed mirror-selfie pose. With the free hand, naturally adjust the blazer lapel, briefly touch the front closure area and smoothly straighten one sleeve. Then rotate the shoulders slightly to show the blazer structure and fit from another angle. Finish with a subtle natural gesture toward the lower area of the frame without touching or interacting with any interface. Use soft natural indoor lighting, realistic shadows, natural breathing, subtle posture shifts, realistic fabric movement and small handheld smartphone micro-jitters. Keep the phone covering the face throughout the entire shot. No speech. No voice. No music. No logos. No watermarks. No text on screen. No platform interface. No distorted hands. No warped clothing. No robotic movement. No exaggerated cinematic movement.', NULL),
  ('UGC-MODA-002', 'Create an ultra-realistic vertical 9:16 UGC mirror-selfie product video. The model wears a fitness top in front of a clean bedroom mirror with the smartphone completely covering the face throughout the video. Preserve the exact outfit, body proportions, environment and product appearance from the reference. Start in a relaxed standing pose. Using the free hand, naturally adjust one shoulder strap and gently touch the front band of the fitness top. Then make a subtle posture change that clearly demonstrates the support, fabric texture and fit of the product. Finish with a small natural gesture toward the lower area of the frame without touching any interface. Use soft natural indoor lighting with realistic shadows, natural breathing, subtle body sway, realistic fabric movement and small handheld smartphone micro-jitters. No speech. No voice. No music. No logos. No watermarks. No text on screen. No platform interface. Do not reveal the face. No distorted hands. No warped product. No robotic movement. No exaggerated cinematic look.', NULL),
  ('UGC-MODA-003', 'Create an ultra-realistic vertical 9:16 UGC mirror-selfie fashion video based on the reference image. Preserve the exact model, body proportions, leggings, smartphone and environment. Keep the smartphone covering the face throughout the entire video. Begin in a relaxed front-facing mirror pose. With the free hand, naturally smooth the fabric around the waist and hip area. Then rotate the hips and torso slightly to one side to demonstrate the leggings fit and silhouette from another angle. Finish in a relaxed side pose. Maintain realistic fabric physics, natural breathing, subtle posture shifts, soft indoor lighting and realistic handheld smartphone micro-movement. No speech. No voice. No music. No logos. No watermarks. No text on screen. No interface. No facial reveal. No body deformation. No distorted hands. No clothing transformation. No robotic movement.', NULL),
  ('UGC-BEAUTY-001', 'Preserve the exact identity, face, hairstyle, beauty product, clothing and environment from the reference image. The subject naturally brings the lip gloss applicator toward the lips and applies a small amount of product using slow controlled movement. The applicator physically contacts the lips while the fingers and wrist articulate naturally. After application, move the applicator slightly away and show the subtle realistic shine and final result. Maintain natural smartphone UGC framing, realistic product scale, skin texture, reflections and lighting. No facial identity changes. No product deformation. No extra fingers. No distorted hands. No exaggerated lip movement. No speech. No lip sync.', NULL),
  ('UGC-BEAUTY-002', 'Preserve the exact subject, product, appearance and environment from the reference image. The subject naturally finishes demonstrating the beauty product and turns slightly toward the camera to show the final result. Hold the product visibly near the face without blocking important facial features. Make one subtle controlled change in head angle so the finish catches the light naturally. End in a confident but realistic product presentation pose. Maintain smartphone UGC aesthetics, realistic hands, skin texture and product proportions. No facial identity changes. No product transformation. No exaggerated movement. No distorted hands. No speech. No lip sync.', NULL),
  ('UNBOXING-002', 'Preserve the exact package, products, hands and environment from the reference. Start with the package already open. A realistic hand reaches inside and removes one visible product at a time. Every object must physically travel from its original location inside the package to the presentation area. Arrange each removed product naturally beside the package. Maintain realistic scale, grip, weight, contact shadows and object permanence. No teleportation. No objects appearing from nowhere. No duplicated products. No distorted fingers. No speech.', NULL),
  ('POV-001', 'Create a realistic first-person POV product interaction. Preserve the exact product, case, hands and environment from the reference. The hand naturally picks up the product and moves it toward the open case. The product physically travels through the scene and is carefully placed inside the correct compartment. Fingers adjust naturally as the product is released. Maintain realistic grip, object weight, scale, perspective and contact shadows. Finish with the product resting naturally inside the case. No teleportation. No floating objects. No duplicated products. No distorted fingers. No speech.', NULL),
  ('TRANSICAO-002', 'Preserve the exact subject, product and environment from the reference image. The subject holds the product naturally and moves it smoothly toward the camera lens in one continuous controlled movement. The product becomes progressively larger because of real physical movement toward the camera until it completely fills and covers the frame. Maintain realistic hand grip, product scale, perspective and motion blur. No digital zoom. No teleportation. No product deformation. No extra fingers. No speech.', NULL),
  ('CTA-002', 'Preserve the exact character, clothing, smartphone and environment from the reference image. Keep the smartphone hand stable. Using the free hand, perform one natural inviting gesture signaling the viewer to come closer. Transition smoothly from this gesture into pointing toward the lower area of the frame using the index finger. Hold the final pointing gesture briefly with a confident natural expression. Movement must remain controlled and realistic. No waving. No peace sign. No hand covering the lens. No exaggerated movement. No extra fingers. No speech. No lip sync.', NULL),
  ('UGC-PRODUTO-001', 'Create an ultra-realistic vertical 9:16 UGC product demonstration based on the supplied reference. Preserve the exact product, hands, environment and lighting. Demonstrate one visible physical property of the product using a controlled interaction appropriate to the supplied item. Any liquid, pressure, bending or physical contact must follow realistic physics. Show the effect progressively rather than instantly. Maintain realistic hands, shadows, reflections, material behavior and object interaction. The demonstrated result must correspond directly to the physical action shown. No magical transformations. No teleportation. No duplicated objects. No distorted fingers. No speech.', NULL),
  ('MODA-LOOK-001', 'Crie um vídeo vertical 9:16, ultra realista, em estilo selfie no espelho, com aparência de gravação feita em celular. A modelo fica em frente ao espelho segurando o celular cobrindo completamente o rosto. Ela muda o peso do corpo de forma natural e alisa a frente do look com a mão livre. Ela dá um pequeno passo para trás para mostrar o look completo e faz um gesto sutil em direção à área inferior esquerda, sem tocar em botões ou interface. O celular deve cobrir o rosto durante todo o vídeo, sem revelar a identidade facial. A cena deve ter luz natural suave, pequenos movimentos reais de mão e corpo, micro-tremores naturais de câmera e foco no produto. Sem fala, sem voz, sem música, sem logos, sem marcas d''água, sem texto na tela, sem interface de plataforma, sem distorcer mãos, sem deformar o produto e sem movimento robótico.', NULL),
  ('MODA-BODY-001', 'Crie um vídeo vertical 9:16, ultra realista, em estilo selfie no espelho, com aparência de gravação feita em celular. A modelo usa um body em frente ao espelho com o celular cobrindo completamente o rosto. A mão livre ajusta o decote e alisa a região da cintura de forma natural. Ela vira levemente o quadril para mostrar o caimento lateral e faz um gesto sutil em direção à área inferior esquerda, sem tocar em botões ou interface. O celular deve cobrir o rosto durante todo o vídeo, sem revelar a identidade facial. A cena deve ter luz natural suave, pequenos movimentos reais de mão e corpo, micro-tremores naturais de câmera e foco no produto. Sem fala, sem voz, sem música, sem logos, sem marcas d''água, sem texto na tela, sem interface de plataforma, sem distorcer mãos, sem deformar o produto e sem movimento robótico.', NULL),
  ('MODA-VESTIDO-001', 'Crie um vídeo vertical 9:16, ultra realista, em estilo selfie no espelho, com aparência de gravação feita em celular. A modelo usa um vestido em frente ao espelho com o celular cobrindo completamente o rosto. Ela segura levemente a lateral do vestido e gira poucos graus para mostrar o movimento natural do tecido. Em seguida volta para a frente, ajusta o vestido e faz um gesto sutil em direção à área inferior esquerda, sem tocar em botões ou interface. Preserve o formato do vestido, fluxo do tecido, caimento e proporções da referência. O celular deve cobrir o rosto durante todo o vídeo. Luz natural suave, sombras realistas, respiração natural, mudanças sutis de postura e micro-tremores de celular. Sem fala, sem voz, sem música, sem logos, sem marcas d''água, sem texto na tela, sem interface, sem mãos distorcidas, sem deformação do vestido e sem movimento robótico.', NULL),
  ('MODA-BLAZER-002', 'Crie um vídeo vertical 9:16, ultra realista, em estilo selfie no espelho, com aparência de gravação feita em celular. A modelo usa um blazer em frente ao espelho com o celular cobrindo completamente o rosto. A mão livre ajusta naturalmente a lapela, passa pela região frontal do botão e alisa uma manga. Ela vira levemente os ombros para mostrar a estrutura da peça e finaliza com um gesto sutil em direção à região inferior do enquadramento, sem tocar em botões ou interface. Preserve lapela, botão, manga, estrutura dos ombros e estilo da peça. Luz natural suave, movimento corporal discreto e micro-tremores naturais de câmera. Sem fala, sem voz, sem música, sem logos, sem marcas d''água, sem texto, sem interface, sem revelar o rosto, sem distorcer mãos, sem deformar o produto e sem movimento robótico.', NULL),
  ('SELFIE-LOOK-002', 'Preserve exatamente a pessoa, roupa, smartphone, espelho e ambiente da imagem de referência. O smartphone permanece cobrindo completamente o rosto. A pessoa começa em pose natural diante do espelho, muda suavemente o peso do corpo e alisa a frente do look com a mão livre. Depois dá um pequeno passo real para trás, aumentando naturalmente a quantidade do look visível no reflexo. Finaliza em pose relaxada. Movimento contínuo, física corporal realista, iluminação consistente e micro-movimentos naturais de câmera. Sem zoom digital. Sem revelar o rosto. Sem transformar roupa. Sem distorcer mãos ou pernas. Sem fala. Sem lip sync.', NULL),
  ('SELFIE-POSE-003', 'Preserve exatamente a pessoa, roupa, celular e ambiente da referência. Em frente ao espelho, mantenha o celular estável e cobrindo o rosto. A personagem transfere suavemente o peso de uma perna para a outra, criando uma pequena mudança natural no quadril e nos ombros. A mão livre faz um ajuste discreto na roupa e retorna a uma posição relaxada. Preserve proporções corporais e física realista do tecido. Sem passos grandes. Sem dança. Sem zoom. Sem revelar o rosto. Sem deformação corporal. Sem fala.', NULL),
  ('CTA-003', 'Preserve exatamente o personagem, produto, roupa e ambiente da referência. Depois de uma pequena ação natural de apresentação, use somente a mão livre para fazer um gesto discreto em direção à parte inferior do enquadramento. O gesto deve indicar visualmente a região abaixo sem tocar em qualquer botão, texto ou interface. Mantenha a mão a uma distância natural do corpo e da câmera. Movimento suave e controlado. Sem apontar para elementos de plataforma. Sem mão cobrindo a lente. Sem acenar. Sem dedos extras. Sem fala. Sem lip sync.', NULL),
  ('MODA-SAIA-001', 'Crie um vídeo vertical 9:16, ultra realista, em estilo selfie no espelho, com aparência de gravação feita em celular. A modelo usa uma saia em frente ao espelho com o celular cobrindo completamente o rosto. A mão livre toca o cós e move suavemente a barra para mostrar o caimento do tecido. Ela muda a postura de forma natural e faz um gesto sutil em direção à área inferior esquerda, sem tocar em botões ou interface. O celular deve cobrir o rosto durante todo o vídeo, sem revelar a identidade facial. A cena deve ter luz natural suave, pequenos movimentos reais de mão e corpo, micro-tremores naturais de câmera e foco no produto. Mostrar o cós, movimento da barra, fluxo do tecido, comprimento e ajuste. Sem fala, sem voz, sem música, sem logos, sem marcas d''água, sem texto na tela, sem interface de plataforma, sem distorcer mãos, sem deformar o produto e sem movimento robótico.', NULL),
  ('MODA-LEGGING-002', 'Crie um vídeo vertical 9:16, ultra realista, em estilo selfie no espelho, com aparência de gravação feita em celular. A modelo usa legging em frente ao espelho com o celular cobrindo completamente o rosto. A mão livre toca o cós e o tecido da coxa enquanto ela muda o peso do corpo naturalmente. Ela vira levemente para mostrar o caimento lateral e faz um gesto sutil em direção à área inferior esquerda, sem tocar em botões ou interface. Preserve cós, elasticidade visual do tecido, ajuste lateral, formato da perna e aparência de conforto. O celular permanece cobrindo o rosto durante todo o vídeo. Luz natural suave, respiração natural, mudanças discretas de postura e micro-tremores realistas do celular. Sem fala, sem voz, sem música, sem logos, sem marcas d''água, sem texto na tela, sem interface, sem distorcer mãos, sem deformar o produto e sem movimento robótico.', NULL),
  ('MODA-TOP-002', 'Crie um vídeo vertical 9:16 ultra realista em estilo selfie no espelho. A modelo usa um top fitness diante de um espelho limpo com o celular cobrindo completamente o rosto. A mão livre ajusta naturalmente uma alça e toca suavemente a faixa frontal do top. Em seguida, ela muda discretamente a postura para demonstrar sustentação, textura do tecido e ajuste da peça. Finaliza com um gesto sutil em direção à área inferior do enquadramento sem tocar em botões ou interface. Preserve o produto e as proporções da referência. Use luz natural suave, sombras realistas, respiração natural, pequenas mudanças de postura e micro-tremores de celular. Sem fala, voz, música, logos, marcas d''água, texto, interface, mãos distorcidas, produto deformado ou movimento robótico.', NULL),
